using namespace std;

class Solution {
public:
    int maxDistance(int side, vector<vector<int>>& points, int k) {
        vector<long long> nums;
        long long s = side;
        for (const auto& p : points) {
            long long x = p[0], y = p[1];
            if (y == 0) nums.push_back(x);
            else if (x == s) nums.push_back(s + y);
            else if (y == s) nums.push_back(2 * s + (s - x));
            else nums.push_back(3 * s + (s - y));
        }
        sort(nums.begin(), nums.end());
        nums.erase(unique(nums.begin(), nums.end()), nums.end());

        int n = nums.size();
        long long P = 4 * s;
        vector<long long> arr = nums;
        for (int i = 0; i < n; i++) arr.push_back(nums[i] + P);

        auto check = [&](long long d) -> bool {
            long long limit = nums[0] + P / k;
            for (int i = 0; i < n; i++) {
                if (nums[i] > limit) break;
                long long last = arr[i];
                bool valid = true;
                for (int step = 0; step < k - 1; step++) {
                    auto it = lower_bound(arr.begin() + i, arr.begin() + i + n, last + d);
                    if (it == arr.begin() + i + n) {
                        valid = false;
                        break;
                    }
                    last = *it;
                }
                if (valid && (arr[i] + P - last >= d)) return true;
            }
            return false;
        };

        long long low = 1, high = s, ans = 0;
        while (low <= high) {
            long long mid = (low + high) / 2;
            if (check(mid)) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return ans;
    }
};

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

class Solution {
    public int maxDistance(int side, int[][] points, int k) {
        List<Long> numsList = new ArrayList<>();
        long s = side;
        for (int[] p : points) {
            long x = p[0], y = p[1];
            if (y == 0) numsList.add(x);
            else if (x == s) numsList.add(s + y);
            else if (y == s) numsList.add(2 * s + (s - x));
            else numsList.add(3 * s + (s - y));
        }
        Collections.sort(numsList);
        List<Long> unique = new ArrayList<>();
        for (long v : numsList) {
            if (unique.isEmpty() || unique.get(unique.size() - 1) != v) {
                unique.add(v);
            }
        }
        int n = unique.size();
        long P = 4 * s;
        long[] arr = new long[2 * n];
        for (int i = 0; i < n; i++) {
            arr[i] = unique.get(i);
            arr[i + n] = unique.get(i) + P;
        }

        long low = 1, high = s, ans = 0;
        while (low <= high) {
            long mid = (low + high) / 2;
            boolean ok = false;
            long limit = arr[0] + P / k;
            for (int i = 0; i < n; i++) {
                if (arr[i] > limit) break;
                long last = arr[i];
                boolean valid = true;
                for (int step = 0; step < k - 1; step++) {
                    int idx = Arrays.binarySearch(arr, i, i + n, last + mid);
                    if (idx < 0) idx = -idx - 1;
                    if (idx >= i + n) {
                        valid = false;
                        break;
                    }
                    last = arr[idx];
                }
                if (valid && (arr[i] + P - last >= mid)) {
                    ok = true;
                    break;
                }
            }
            if (ok) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return (int) ans;
    }
}

/**
 * @param {number} side
 * @param {number[][]} points
 * @param {number} k
 * @return {number}
 */
var maxDistance = function(side, points, k) {
    const s = side;
    const nums = [];
    for (const [x, y] of points) {
        if (y === 0) nums.push(x);
        else if (x === s) nums.push(s + y);
        else if (y === s) nums.push(2 * s + (s - x));
        else nums.push(3 * s + (s - y));
    }
    nums.sort((a, b) => a - b);
    const unique = [];
    for (const v of nums) {
        if (!unique.length || unique[unique.length - 1] !== v) {
            unique.push(v);
        }
    }
    const n = unique.length;
    const P = 4 * s;
    const arr = unique.concat(unique.map(v => v + P));

    function lowerBound(target, start, end) {
        let lo = start, hi = end;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] >= target) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    function check(d) {
        const limit = unique[0] + Math.floor(P / k);
        for (let i = 0; i < n; i++) {
            if (unique[i] > limit) break;
            let last = arr[i];
            let valid = true;
            for (let step = 0; step < k - 1; step++) {
                const idx = lowerBound(last + d, i, i + n);
                if (idx >= i + n) {
                    valid = false;
                    break;
                }
                last = arr[idx];
            }
            if (valid && (arr[i] + P - last >= d)) return true;
        }
        return false;
    }

    let low = 1, high = s, ans = 0;
    while (low <= high) {
        const mid = (low + high) >> 1;
        if (check(mid)) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
};
